from copy import deepcopy
from math import ceil

from taf.rfrl.l3_call.enviornment.env import Env
from taf.rfrl.l3_call.enviornment.exceptions import InvalidCellType
from taf.rfrl.l3_call.logger.l3_call_logger import log_to_console, log_result
from taf.rfrl.l3_call.connection.api_connection.api_connection_factory import ApiConnectionFactory
from taf.rfrl.l3_call.pcap.pcap_factory import VerifyPcapFactory


class ClassicalEnv(Env):
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self):
        super(ClassicalEnv, self).__init__()
        self._connection = None
        self._cells_info = {}
        self._cell_specific_info = {}
        self._delta_id = None
        self._connection_alias = None
        self._node = None
        self._mode = None

    def _is_callable(self, cell_distname):
        if "WNCEL" not in cell_distname and "GNCEL" not in cell_distname:
            return True
        else:
            raise InvalidCellType("You are trying to call WCDMA/GSM cell. This is not possible yet, please"
                                  " contact taf.rfrl.l3_call developers for more info!")

    def _get_number_of_super_subcells(self, cell_distname):
        cell = self._create_cell(cell_distname=cell_distname, bts_connection_alias=self._connection_alias)
        return cell.get_number_of_super_subcells()

    def _clean_up_after_call(self, close_connection_to_bts):
        self._open_api_connection()
        self._delta = self._create_delta(connection_alias=self._connection_alias, id="clean_up_after_call_delta")
        self._make_cells_callable()
        self._cell_ids = None
        self._called_cells.clear()
        self.ignored_cells_distnames.clear()

        if close_connection_to_bts:
            self._connection.disconnect(connection=self._connection_alias)

    def _make_cells_callable(self):
        for not_called_cell in self._not_called_cells_distnames:
            cell = self._create_cell(cell_distname=not_called_cell, bts_connection_alias=self._connection_alias)
            cell.make_callable(delta=self._delta)
        self._perform_delta_recommissioning(delta=self._delta)

    def _prepare_setup_to_call(self):
        self._open_api_connection()
        self._get_cells_info_for_all_rats()
        for called_cell_distname in self.called_cells_distnames:
            self._cell = self._create_cell(cell_distname=called_cell_distname,
                                           bts_connection_alias=self._connection_alias)
            self._called_cells.append(self._cell)
            self._handle_dss()
            self._prepare_called_cell()

        self._prepare_not_called_cells()

    def _make_selected_cells_unbarred(self, cells_distnames):
        self._delta = self._create_delta(connection_alias=self._connection_alias, id="l3_call_gnb_delta_id")
        for cell_distname in cells_distnames:
            self._cell = self._create_cell(cell_distname=cell_distname,
                                           bts_connection_alias=self._connection_alias)
            self._cell.make_unbarred(delta=self._delta)
        self._perform_delta_recommissioning(delta=self._delta)

    def _make_selected_cells_barred(self, cells_distnames):
        self._delta = self._create_delta(connection_alias=self._connection_alias, id="l3_call_gnb_delta_id")

        for cell_distname in cells_distnames:
            self._cell = self._create_cell(cell_distname=cell_distname, bts_connection_alias=self._connection_alias)
            self._cell.make_barred(delta=self._delta)
        self._perform_delta_recommissioning(delta=self._delta)

    def _prepare_called_cell(self):
        self._get_cell_specific_info(distname=self._cell.distname)
        self._called_cell_spectrum = self._cell.get_spectrum(cells_info=self._cells_info,
                                                             cell_specific_info=self._cell_specific_info)
        self._cell.make_callable()
        log_result("Cell {} is ready to be called!".format(self._cell.distname))

    def _prepare_not_called_cells(self):
        self._open_api_connection()
        self._get_not_called_cells_distnames()
        self._delta = self._create_delta(connection_alias=self._connection_alias, id=self._delta_id)
        for not_called_cell_distname in self._not_called_cells_distnames:
            self._get_cell_specific_info(distname=not_called_cell_distname)
            self._prepare_not_called_cell(not_called_cell_distname=not_called_cell_distname)

        self._perform_delta_recommissioning(delta=self._delta,
                                            delay=self._calculate_delay_after_parameter_recommissioning())

    def _calculate_delay_after_parameter_recommissioning(self):
        """
        Due to PR765927 the delay after parameter recommissioning
        is needed when there are more than LTE 6 cells on the setup (extra 20s for each group of 6)
        """
        number_of_lte_cells = 0
        for not_called_cell_distname in self._not_called_cells_distnames:
            if "LNCEL" in not_called_cell_distname:
                number_of_lte_cells += 1

        if number_of_lte_cells <= 6:
            return 0
        return (ceil(number_of_lte_cells / 6) - 1) * 20

    def _prepare_not_called_cell(self, not_called_cell_distname):
        cell = self._create_cell(cell_distname=not_called_cell_distname,
                                 bts_connection_alias=self._connection_alias)
        cell_spectrum = cell.get_spectrum(cells_info=self._cells_info, cell_specific_info=self._cell_specific_info)
        shared_spectrum = self._is_spectrum_shared(cell_spectrum_1=self._called_cell_spectrum,
                                                   cell_spectrum_2=cell_spectrum)

        if shared_spectrum:
            cell = self._create_cell(cell_distname=not_called_cell_distname, shared_spectrum=True,
                                     bts_connection_alias=self._connection_alias)
        cell.make_uncallable(delta=self._delta)

    def _get_not_called_cells_distnames(self):
        all_cells_distnames = self._connection.get_cells_distnames(connection=self._connection_alias)
        self._not_called_cells_distnames = self._exclude_cells_from_all_cells_list(
            all_cells_distnames=all_cells_distnames,
            cells=self._get_distnames_of_cells_to_exclude())

        log_result("List of not_called_cells for {}: {}".format(self._cell.distname,
                                                                self._not_called_cells_distnames))

    def _get_cell_id(self, called_cell_distname):
        self._cell = self._create_cell(cell_distname=called_cell_distname, bts_connection_alias=self._connection_alias)
        self._cell.id = self._cell.get_cell_id()
        return self._make_cell_ids_dict()

    def _get_distnames_of_cells_to_exclude(self):
        dss_pairs = [cell.dss_pair for cell in self._called_cells if cell.dss_pair]
        enb_pairs = [cell.enb_pair for cell in self._called_cells if cell.enb_pair]
        return dss_pairs + enb_pairs + self.called_cells_distnames + self.ignored_cells_distnames

    def _exclude_cells_from_all_cells_list(self, all_cells_distnames, cells):
        cells_distnames = deepcopy(all_cells_distnames)
        for not_called_cell in all_cells_distnames:
            for called_cell in cells:
                if called_cell == not_called_cell:
                    try:
                        cells_distnames.remove(called_cell)
                    except ValueError:
                        pass
        return cells_distnames

    def _get_cells_info_for_all_rats(self):
        rats = ["nr", "lte", "wcdma", "gsm"]
        self._cells_info = {rat: self._connection.get_cells_info(
            connection=self._connection_alias, cell_type=rat) for rat in rats}

    def _get_cell_specific_info(self, distname):
        self._cell_specific_info = self._connection.get_cell_specific_info(
            connection=self._connection_alias, distname=distname)

    def _open_api_connection(self):
        self._connection = ApiConnectionFactory.create_connection(ran="classical", node=self._node)
        self._connection.connect_to(name=self._connection_alias)

    def _verify_pcap(self, cell_distname, pcap_path, attach_should_be_possible=True):
        log_to_console("Verifying PCAP file...")

        self.pcap = VerifyPcapFactory.create_pcap_instance(ran=self._ran, mode=self._mode, cell_distname=cell_distname)
        self.pcap.verify_pcap_file(pcap_path=pcap_path, attach_should_be_possible=attach_should_be_possible)

        log_result("PCAP content is correct")

    def _verify_pcap_after_parallel_call(self, cell_distname, pcap_path, number_of_expected_attach_msgs):
        log_to_console("Verifying PCAP file after parallel call...")

        self.pcap = VerifyPcapFactory.create_pcap_instance(ran=self._ran, mode=self._mode, cell_distname=cell_distname)
        self.pcap.verify_pcap_file_after_parallel_call(pcap_path=pcap_path,
                                                       number_of_expected_attach_msgs=number_of_expected_attach_msgs)

        log_result("PCAP content is correct")

    def _make_cell_ids_dict(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._make_cell_ids_dict.__name__))
